import styles from './join.module.css'

export type JoinOrientation = 'horizontal' | 'vertical'

export interface JoinProps {
  children: React.ReactNode
  /**
   * Axis the joined children flow along: `horizontal` for a row, `vertical` for a column.
   * Inner corners are squared off either way.
   *
   * @defaultValue `horizontal`
   * @see the component manifest
   */
  orientation?: JoinOrientation
  className?: string
}

export function Join({ children, orientation = 'horizontal', className }: JoinProps) {
  return (
    <div
      className={[styles.join, className].filter(Boolean).join(' ')}
      data-orientation={orientation}
    >
      {children}
    </div>
  )
}

@layer cascivo.component {
  .join {
    display: inline-flex;
  }

  .join[data-orientation='horizontal'] {
    flex-direction: row;
  }
  .join[data-orientation='vertical'] {
    flex-direction: column;
  }

  .join[data-orientation='horizontal'] > :first-child:not(:last-child) {
    border-start-end-radius: 0 !important;
    border-end-end-radius: 0 !important;
  }
  .join[data-orientation='horizontal'] > :last-child:not(:first-child) {
    border-start-start-radius: 0 !important;
    border-end-start-radius: 0 !important;
  }
  .join[data-orientation='horizontal'] > :not(:first-child):not(:last-child) {
    border-radius: 0 !important;
  }

  .join[data-orientation='vertical'] > :first-child:not(:last-child) {
    border-end-start-radius: 0 !important;
    border-end-end-radius: 0 !important;
  }
  .join[data-orientation='vertical'] > :last-child:not(:first-child) {
    border-start-start-radius: 0 !important;
    border-start-end-radius: 0 !important;
  }
  .join[data-orientation='vertical'] > :not(:first-child):not(:last-child) {
    border-radius: 0 !important;
  }

  .join[data-orientation='horizontal'] > :not(:first-child) {
    border-inline-start-width: 0;
  }
  .join[data-orientation='vertical'] > :not(:first-child) {
    border-block-start-width: 0;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Join',
  description:
    'Groups adjacent children into a seamless joined element by removing interior borders and radii',
  category: 'layout',
